const LEVELS=DATA.map((defs,i)=>{const pieces=defs.map(([t,r,x,y],id)=>({id,t,r,x,y,f:false}));const cells=pieces.flatMap(p=>shape(p.t,p.r).map(([x,y])=>[x+p.x,y+p.y]));return {id:i,pieces,cells,w:Math.max(...cells.map(p=>p[0]))+1,h:Math.max(...cells.map(p=>p[1]))+1}});
// Legacy IDs remain stable so existing links and history still resolve correctly.
CATALOG.forEach((entry,index)=>{
 const pieces=entry.defs.map(([t,r,x,y,f],id)=>({id,t,r,x,y,f}));
 LEVELS.push({id:LEVELS.length,pieces,cells:entry.cells,w:Math.max(...entry.cells.map(c=>c[0]))+1,h:Math.max(...entry.cells.map(c=>c[1]))+1,name:entry.name,number:index+1,tier:pieces.length<=3?'入门':pieces.length<=5?'进阶':pieces.length<=8?'挑战':'专家'});
});
function levelTitle(id){const l=LEVELS[id];return l.number?`第 ${String(l.number).padStart(2,'0')} 关 · ${l.name}`:`旧版第 ${id+1} 关`}
function nextLevel(){return level<LEGACY_COUNT||level===LEVELS.length-1?LEGACY_COUNT:level+1}

let level=0,placed=[],selected=0,rotation=0,flipped=false,started=null,elapsed=0,done=false,assisted=false,undoStack=[],hover=null,drag=null,history=[];
try{history=JSON.parse(localStorage.getItem('polyomino-history')||'[]');if(!Array.isArray(history))history=[];document.body.dataset.theme=localStorage.getItem('polyomino-theme')||'day'}catch{}
const key=p=>p.join(','), cellsOf=p=>shape(LEVELS[level].pieces[p.id].t,p.r,p.f).map(([x,y])=>[x+p.x,y+p.y]);
function valid(p,others=placed){const target=new Set(LEVELS[level].cells.map(key)),used=new Set(others.filter(q=>q.id!==p.id).flatMap(cellsOf).map(key));return cellsOf(p).every(c=>target.has(key(c))&&!used.has(key(c)))}
function el(tag,attrs,parent){let e=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e}
function draw(svg,li,ps=[],options={}){svg.replaceChildren();let l=LEVELS[li];svg.setAttribute('viewBox',`-0.55 -0.55 ${l.w+1.1} ${l.h+1.1}`);l.cells.forEach(([x,y])=>{el('rect',{x:x+.035,y:y+.035,width:.93,height:.93,rx:.16,fill:'var(--hole)'},svg);el('circle',{cx:x+.5,cy:y+.5,r:.075,fill:'var(--muted)',opacity:.25},svg)});ps.forEach(p=>{let g=el('g',{'data-piece':p.id,opacity:options.selected&&!options.selected.has(p.id)?.2:1},svg);shape(l.pieces[p.id].t,p.r,p.f).forEach(([a,b])=>{let x=a+p.x,y=b+p.y;el('rect',{x:x+.025,y:y+.025,width:.95,height:.95,rx:.16,fill:COLORS[p.id%COLORS.length]},g);el('circle',{cx:x+.5,cy:y+.5,r:.105,fill:'#fff',opacity:.8},g)});});}
function mini(t,r=0,f=false){const c=shape(t,r,f),w=Math.max(...c.map(p=>p[0]))+1,h=Math.max(...c.map(p=>p[1]))+1;return `<svg viewBox="-.2 -.2 ${w+.4} ${h+.4}" aria-hidden="true">${c.map(([x,y])=>`<rect x="${x+.025}" y="${y+.025}" width=".95" height=".95" rx=".16" fill="currentColor"/><circle cx="${x+.5}" cy="${y+.5}" r=".1" fill="white" opacity=".8"/>`).join('')}</svg>`}
function render(){let l=LEVELS[level];$('#level').textContent=levelTitle(level) ;$('#progress').textContent=`${placed.reduce((n,p)=>n+SHAPES[l.pieces[p.id].t].length,0)} / ${l.cells.length} 格`;$('#remaining').textContent=`${l.pieces.length-placed.length} 块`;draw($('#board'),level,placed);if(hover&&selected!==null&&!done){let p={id:selected,r:rotation,f:flipped,...hover};cellsOf(p).forEach(([x,y])=>el('rect',{x:x+.06,y:y+.06,width:.88,height:.88,rx:.15,fill:valid(p)?COLORS[selected%COLORS.length]:'#c45252',opacity:.45,'pointer-events':'none'},$('#board')))}$('#tray').innerHTML=l.pieces.map(p=>`<button class="piece ${selected===p.id?'active':''} ${placed.some(q=>q.id===p.id)?'used':''}" data-id="${p.id}" aria-label="积木 ${p.id+1}，${p.t} 形" aria-pressed="${selected===p.id}" style="color:${COLORS[p.id%COLORS.length]}">${mini(p.t,selected===p.id?rotation:0,selected===p.id?flipped:false)}<small>${p.id+1}</small></button>`).join('');$('#selected').innerHTML=selected===null?'':mini(l.pieces[selected].t,rotation,flipped);$('#selected').style.color=COLORS[selected%COLORS.length];$('#rotate').disabled=$('#flip').disabled=selected===null||done;$('#undo').disabled=!undoStack.length||done;$('#remove').disabled=done||!placed.some(p=>p.id===selected);}
function clock(){if(started!==null&&!done)elapsed=performance.now()-started;$('#timer').textContent=format(elapsed);requestAnimationFrame(clock)}
function format(ms){ms=Math.floor(ms);return `${String(Math.floor(ms/60000)).padStart(2,'0')}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}.${String(ms%1000).padStart(3,'0')}`}
function hint(t){$('#hint').textContent=t}
function saveHistory(status){if(!placed.length&&!elapsed)return;const rec={id:globalThis.crypto?.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`,level,placed:structuredClone(placed),elapsed:Math.floor(elapsed),date:new Date().toISOString(),status,assisted};history.unshift(rec);history=history.slice(0,500);try{localStorage.setItem('polyomino-history',JSON.stringify(history))}catch{hint('浏览器存储不可用，请导出历史备份。')}}
function load(li,ps=[]){level=li;placed=structuredClone(ps);selected=LEVELS[li].pieces.find(p=>!ps.some(q=>p.id===q.id))?.id??null;rotation=0;flipped=false;started=null;elapsed=0;done=ps.length===LEVELS[li].pieces.length;assisted=false;undoStack=[];hover=null;render();hint(done?'这是已完成的局面。可从菜单重新开始。':'选择积木，再点击棋盘放置；也可拖入棋盘。')}
function put(x,y){if(selected===null||done)return;let p={id:selected,r:rotation,f:flipped,x,y};if(!valid(p)){hint('这里放不下，请调整位置或旋转积木。');return}undoStack.push(structuredClone(placed));placed=placed.filter(q=>q.id!==selected);placed.push(p);if(started===null)started=performance.now();selected=LEVELS[level].pieces.find(q=>!placed.some(p=>q.id===p.id))?.id??null;rotation=0;flipped=false;hover=null;if(placed.length===LEVELS[level].pieces.length){elapsed=performance.now()-started;done=true;saveHistory('完成');show('完成拼图',`<p>用时 <strong>${format(elapsed)}</strong></p><p class="note">本次游玩已保存到本地历史。</p><div class="row"><button id="finishStay">查看棋盘</button><button class="primary" id="finishNext">下一关</button></div>`);$('#finishStay').onclick=close;$('#finishNext').onclick=()=>confirmAction('进入下一关？','当前完成记录已经保存。',()=>load(nextLevel()));}render()}
function show(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){$('#modal').close()}
function confirmAction(title,text,fn){show(title,`<p class="note">${text}</p><div class="row"><button id="cancel">取消</button><button id="confirm" class="primary">确认</button></div>`);$('#cancel').onclick=close;$('#confirm').onclick=()=>{close();fn()}}
$('#close').onclick=close;
$('#rotate').onclick=()=>{rotation=(rotation+1)%4;render()};$('#flip').onclick=()=>{flipped=!flipped;render()};$('#undo').onclick=()=>{placed=undoStack.pop();selected=LEVELS[level].pieces.find(q=>!placed.some(p=>p.id===q.id))?.id??null;hover=null;render()};
function point(e){let s=$('#board'),p=new DOMPoint(e.clientX,e.clientY).matrixTransform(s.getScreenCTM().inverse());return {x:Math.floor(p.x),y:Math.floor(p.y)}}
$('#tray').onpointerdown=e=>{let b=e.target.closest('[data-id]');if(!b||done)return;selected=+b.dataset.id;let p=placed.find(p=>p.id===selected);rotation=p?.r||0;flipped=p?.f||false;drag={x:e.clientX,y:e.clientY,source:'tray',moved:false};hover=null;render()};
$('#board').onpointerdown=e=>{if(done)return;const at=point(e),p=placed.find(p=>cellsOf(p).some(c=>c[0]===at.x&&c[1]===at.y));if(p){selected=p.id;rotation=p.r;flipped=p.f;drag={x:e.clientX,y:e.clientY,source:'board',moved:false,dx:at.x-p.x,dy:at.y-p.y};render();hint('可拖动这块积木，或旋转后点击新位置。')}else{drag={x:e.clientX,y:e.clientY,source:'empty',moved:false};}};
window.addEventListener('pointermove',e=>{if(!drag||done)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>5)drag.moved=true;if(drag.moved){let p=point(e);hover={x:p.x-(drag.dx||0),y:p.y-(drag.dy||0)};render()}});
window.addEventListener('pointerup',e=>{if(!drag)return;let d=drag;drag=null;let r=$('#board').getBoundingClientRect();if(e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom&&(d.moved||d.source==='empty')){let p=point(e);put(p.x-(d.dx||0),p.y-(d.dy||0))}hover=null;render()});window.addEventListener('pointercancel',()=>{drag=null;hover=null;render()});
document.addEventListener('keydown',e=>{if($('#modal').open)return;if(e.key.toLowerCase()==='r')$('#rotate').click();if(e.key.toLowerCase()==='f')$('#flip').click();if(e.key==='Delete'&&selected!==null&&!done&&placed.some(p=>p.id===selected)){undoStack.push(structuredClone(placed));placed=placed.filter(p=>p.id!==selected);render()}});
function menu(){show('菜单',`<div class="menu-grid"><button id="levels">切换关卡</button><button id="restart">重新开始</button><button id="answer">查看答案</button><button id="share">分享局面</button><button id="history">历史记录</button><button id="fullscreen">${document.fullscreenElement?'退出全屏':'全屏'}</button></div><p class="note">显示模式</p><div class="row"><button data-theme="day">日间</button><button data-theme="night">夜间</button><button data-theme="dim">低亮度</button></div><p class="note">点击或拖放积木。再次选择已放置的积木可移动。旋转 R · 翻转 F。计时从首次有效落子开始，完成时停止。</p>`);$('#levels').onclick=levels;$('#restart').onclick=()=>confirmAction('重新开始本关？','当前游玩将保存到历史，计时归零。',()=>{if(!done)saveHistory('未完成');load(level)});$('#answer').onclick=()=>confirmAction('查看本关答案？','当前游玩将保存到历史，棋盘将显示答案并停止计时。',()=>{if(!done)saveHistory('未完成');done=true;assisted=true;placed=structuredClone(LEVELS[level].pieces);selected=null;render();hint('正在查看答案。通过菜单重新开始可再次挑战。')});$('#share').onclick=share;$('#history').onclick=showHistory;$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();close()}catch{hint('当前浏览器不支持全屏。');close()}};document.querySelectorAll('[data-theme]').forEach(b=>{if(b.tagName==='BUTTON'){b.classList.toggle('primary',b.dataset.theme===document.body.dataset.theme);b.onclick=()=>{document.body.dataset.theme=b.dataset.theme;try{localStorage.setItem('polyomino-theme',b.dataset.theme)}catch{}menu()}}})}
$('#menu').onclick=menu;
function levels(){show('切换关卡',`<div class="level-grid">${LEVELS.filter(l=>l.number).map(l=>`<button data-level="${l.id}" ${l.id===level?'class="primary"':''}><svg></svg><span>${levelTitle(l.id)}</span><small>${l.tier} · ${l.pieces.length} 块 · ${l.w}×${l.h}</small></button>`).join('')}</div>`);document.querySelectorAll('[data-level]').forEach(b=>{draw(b.querySelector('svg'),+b.dataset.level);b.onclick=()=>confirmAction(`进入${levelTitle(+b.dataset.level)}？`,'当前未完成的游玩将保存到历史。',()=>{if(!done)saveHistory('未完成');load(+b.dataset.level)})})}

function encode(data){return btoa(JSON.stringify(data)).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'')}
function decode(s){return JSON.parse(atob(s.replaceAll('-','+').replaceAll('_','/')))}
function validate(data){if(!data||!Number.isInteger(data.level)||!LEVELS[data.level]||!Array.isArray(data.placed)||data.placed.length>LEVELS[data.level].pieces.length)throw Error('无效关卡');let l=LEVELS[data.level],seen=new Set(),occupied=new Set(),target=new Set(l.cells.map(key));for(let p of data.placed){if(!p||!Number.isInteger(p.id)||!l.pieces[p.id]||seen.has(p.id)||!Number.isInteger(p.r)||p.r<0||p.r>3||typeof p.f!=='boolean'||!Number.isInteger(p.x)||!Number.isInteger(p.y))throw Error('无效积木');seen.add(p.id);for(let [a,b]of shape(l.pieces[p.id].t,p.r,p.f)){let k=key([a+p.x,b+p.y]);if(!target.has(k)||occupied.has(k))throw Error('积木越界或重叠');occupied.add(k)}}return data}
function share(){let chosen=new Set(placed.map(p=>p.id));show('分享局面',`<div class="row"><button id="shareEmpty">只分享题目</button><button id="shareSome" class="primary">包含选中积木</button></div><p class="note">点击下方已放置积木，选择要分享的部分。淡色积木不会包含在链接中。</p><svg id="sharePreview" class="preview" aria-label="选择分享的积木"></svg><button id="makeLink" class="primary" style="width:100%">创建分享链接</button><div id="linkArea"></div>`);let refresh=()=>draw($('#sharePreview'),level,placed,{selected:chosen});refresh();$('#sharePreview').onclick=e=>{let g=e.target.closest('[data-piece]');if(g){let id=+g.dataset.piece;chosen.has(id)?chosen.delete(id):chosen.add(id);refresh()}};$('#shareEmpty').onclick=()=>{chosen.clear();refresh();$('#shareEmpty').classList.add('primary');$('#shareSome').classList.remove('primary')};$('#shareSome').onclick=()=>{chosen=new Set(placed.map(p=>p.id));refresh();$('#shareSome').classList.add('primary');$('#shareEmpty').classList.remove('primary')};$('#makeLink').onclick=()=>{let url=new URL(location.href);url.hash='p='+encode({v:1,level,placed:placed.filter(p=>chosen.has(p.id))});$('#linkArea').innerHTML='<p class="note">打开链接即进入所选局面，计时从首次落子开始。</p><input class="link" readonly aria-label="分享链接"><div class="row"><button id="copy">复制链接</button><button id="nativeShare">系统分享</button></div>';$('.link').value=url.href;$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(url.href);$('#copy').textContent='已复制'}catch{$('.link').select();$('#copy').textContent='请长按链接复制'}};$('#nativeShare').onclick=async()=>{if(navigator.share){try{await navigator.share({title:levelTitle(level),url:url.href})}catch{}}else{$('.link').select();$('#nativeShare').textContent='请复制链接分享'}}}}
function showHistory(){show('历史记录',`<div class="row"><button id="export">导出 JSON</button><button id="importButton">导入 JSON</button></div><p class="note">保存在此浏览器，最多 500 条。点击记录可恢复局面，重新计时。</p><div id="historyList"></div>`);let box=$('#historyList');if(!history.length)box.innerHTML='<p class="note">暂无游玩记录。</p>';history.forEach(r=>{try{validate(r)}catch{return}let b=document.createElement('button');b.className='history';b.innerHTML='<svg></svg><span></span>';b.querySelector('span').textContent=`${levelTitle(r.level)} · ${r.status==='完成'?'完成':'未完成'} · ${format(r.elapsed)}\n${new Date(r.date).toLocaleString('zh-CN')}`;b.querySelector('span').style.whiteSpace='pre-line';draw(b.querySelector('svg'),r.level,r.placed);b.onclick=()=>confirmAction('恢复此局面？','当前游玩将保存到历史；恢复后重新计时。',()=>{if(!done)saveHistory('未完成');load(r.level,r.placed)});box.append(b)});$('#export').onclick=()=>{let url=URL.createObjectURL(new Blob([JSON.stringify({version:1,records:history},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`polyomino-history-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#importButton').onclick=()=>$('#import').click()}
$('#import').onchange=async e=>{let file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5e6)throw Error('文件不能超过 5 MB');let data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.records)||data.records.length>500)throw Error('历史文件格式不正确');data.records.forEach(r=>{validate(r);if(typeof r.id!=='string'||!Number.isFinite(r.elapsed)||r.elapsed<0||r.elapsed>1e12||!Number.isFinite(Date.parse(r.date)))throw Error('记录数据不正确')});confirmAction(`导入 ${data.records.length} 条记录？`,'将与本地历史合并，重复记录跳过，最多保留最近 500 条。',()=>{history=[...new Map([...history,...data.records].map(r=>[r.id,r])).values()].sort((a,b)=>Date.parse(b.date)-Date.parse(a.date)).slice(0,500);try{localStorage.setItem('polyomino-history',JSON.stringify(history));showHistory()}catch{show('保存失败','<p>浏览器存储不可用，请导出备份。</p>')}})}catch(err){show('无法导入','<p id="errorText"></p>');$('#errorText').textContent=err.message}};
function openHash(initial=false){if(!location.hash.startsWith('#p='))return false;try{let d=validate(decode(location.hash.slice(3)));if(initial)load(d.level,d.placed);else confirmAction('打开分享局面？','当前游玩将保存到历史并重新计时。',()=>{if(!done)saveHistory('未完成');load(d.level,d.placed)});return true}catch{show('链接无效','<p>分享数据损坏或不适用于当前版本。</p>');return false}}
window.addEventListener('hashchange',()=>openHash());if(!openHash(true))load(LEGACY_COUNT);clock();

$('#remove').onclick=()=>{if(done||selected===null)return;undoStack.push(structuredClone(placed));placed=placed.filter(p=>p.id!==selected);hover=null;render()};
window.addEventListener('pagehide',()=>{if(!done){if(started!==null)elapsed=performance.now()-started;saveHistory('未完成')}});
